description:
Write the pure core of a command-line tool: `run(argv, readFile)` returns `{ code, stdout, stderr }` instead of printing, so it can be tested. `readFile(name)` returns a file's text, or throws an error with `code: "ENOENT"` if the file does not exist.

The tool is used as `csvsum FILE COLUMN [--top N]`:

- Read the CSV (first line is the header, comma-separated, no quoting). Add up the numeric `COLUMN` grouped by the **first** column.
- `stdout` lists each group and its total, highest first (ties alphabetically), one per line as `"<group>: <total>"`, each line ending in `"\n"`. `--top N` keeps only the first `N`.
- Rows whose value is not a number are skipped and counted; if any were skipped, `stderr` is `"skipped <n> rows\n"`.
- Errors give `code` 1 and a message on `stderr` ending in `"\n"`, with empty `stdout`: a missing file (`"no such file: FILE"`), an unknown column (`"no column: COLUMN"`).
- Wrong usage (fewer than two positional arguments) gives `code` 2 and `stderr` `"usage: csvsum FILE COLUMN [--top N]\n"`.
- Success gives `code` 0.

```javascript
const files = { "sales.csv": "region,amount\nnorth,10\nsouth,5\nnorth,2.5\nwest,oops\n" };
run(["sales.csv", "amount"], name => files[name]);
// { code: 0, stdout: "north: 12.5\nsouth: 5\n", stderr: "skipped 1 rows\n" }
```

starter.solution.js:
function run(argv, readFile) {
  return { code: 0, stdout: "", stderr: "" };
}

solution.solution.js:
function run(argv, readFile) {
  const usage = { code: 2, stdout: "", stderr: "usage: csvsum FILE COLUMN [--top N]\n" };
  const positional = [];
  let top = Infinity;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--top" && i + 1 < argv.length) top = Number(argv[++i]);
    else positional.push(argv[i]);
  }
  if (positional.length < 2 || !(top > 0)) return usage;
  const [file, column] = positional;

  let text;
  try {
    text = readFile(file);
  } catch (e) {
    if (e && e.code === "ENOENT") return { code: 1, stdout: "", stderr: `no such file: ${file}\n` };
    throw e;
  }

  const lines = text.split(/\r?\n/).filter(line => line.trim() !== "");
  const header = (lines[0] ?? "").split(",");
  const index = header.indexOf(column);
  if (index < 0) return { code: 1, stdout: "", stderr: `no column: ${column}\n` };

  const totals = new Map();
  let skipped = 0;
  for (const line of lines.slice(1)) {
    const cells = line.split(",");
    const value = Number(cells[index]);
    if (cells[index] === undefined || cells[index].trim() === "" || Number.isNaN(value)) {
      skipped++;
      continue;
    }
    totals.set(cells[0], (totals.get(cells[0]) ?? 0) + value);
  }

  const rows = [...totals].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, top);
  return {
    code: 0,
    stdout: rows.map(([group, total]) => `${group}: ${total}\n`).join(""),
    stderr: skipped ? `skipped ${skipped} rows\n` : "",
  };
}

unitTests:
const files = {
  "sales.csv": "region,amount\nnorth,10\nsouth,5\nnorth,2.5\nwest,oops\n",
  "ties.csv": "name,score\r\nb,3\r\na,3\r\nc,7\r\n",
};
const reader = name => {
  if (!(name in files)) { const e = new Error("missing"); e.code = "ENOENT"; throw e; }
  return files[name];
};

test("totals, skipped rows", () => {
  checkEq(run(["sales.csv", "amount"], reader), { code: 0, stdout: "north: 12.5\nsouth: 5\n", stderr: "skipped 1 rows\n" });
});

test("ties and --top", () => {
  checkEq(run(["ties.csv", "score"], reader).stdout, "c: 7\na: 3\nb: 3\n");
  checkEq(run(["ties.csv", "score", "--top", "2"], reader), { code: 0, stdout: "c: 7\na: 3\n", stderr: "" });
});

test("errors and usage", () => {
  checkEq(run(["nope.csv", "x"], reader), { code: 1, stdout: "", stderr: "no such file: nope.csv\n" });
  checkEq(run(["sales.csv", "price"], reader), { code: 1, stdout: "", stderr: "no column: price\n" });
  checkEq(run(["sales.csv"], reader), { code: 2, stdout: "", stderr: "usage: csvsum FILE COLUMN [--top N]\n" });
});

